<script setup lang="ts">
import { useColumnWidths } from '@/features/table/useColumnWidths'

import TableSortHeader from '@/components/TableSortHeader.vue'
import TablePager from '@/components/TablePager.vue'
import { useDebouncedValue } from '@/features/table/useTableView'
import { useClientTable } from '@/features/table/useClientTable'

import {ref,reactive,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useAuthStore} from '@/stores/auth'
import {getResourceTree} from '@/api/resource'
import {ops,listOps,errorMessage} from '@/api/asset-ops'
const auth=useAuthStore(),sites=ref<any[]>([]),rooms=ref<any[]>([]),busy=ref(false),loading=ref(false),siteDialog=ref(false),site=reactive<any>({})
const canWrite=computed(()=>auth.user?.roles?.some(r=>['system_admin','asset_manager'].includes(r.code)))
async function load(){loading.value=true;try{const [items,tree]=await Promise.all([listOps('sites'),getResourceTree()]);sites.value=items;rooms.value=(tree.items||[]).flatMap((d:any)=>(d.rooms||[]).map((r:any)=>({...r,label:d.name+' / '+r.name})))}catch(e){ElMessage.error(errorMessage(e))}finally{loading.value=false}}
function addSite(){Object.keys(site).forEach(k=>delete site[k]);Object.assign(site,{name:'',region:'',kind:'OFFICE',roomId:null,address:''});siteDialog.value=true}
function editSite(row:any){Object.keys(site).forEach(k=>delete site[k]);Object.assign(site,row);siteDialog.value=true}
async function deleteSite(row:any){try{await ElMessageBox.confirm('确认删除位置“'+row.name+'”？已被资产、备件、规则或盘点引用的位置不能删除。','删除资产位置',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})}catch{return}busy.value=true;try{await ops(`sites/${row.id}?version=${row.version}`,'DELETE');await load();ElMessage.success('位置已删除并记录审计')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function saveSite(){busy.value=true;try{await ops(site.id?`sites/${site.id}`:'sites',site.id?'PUT':'POST',{...site,roomId:site.kind==='OFFICE'?null:site.roomId||null});siteDialog.value=false;await load();ElMessage.success(site.id?'资产位置已更新':'资产位置已建立')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}

const search = ref('')
const query = useDebouncedValue(search)
const filteredRows = computed(() => sites.value.filter(row => !query.value.trim() || [row.region, row.name, row.address].some(value => String(value || '').toLowerCase().includes(query.value.trim().toLowerCase()))))
function clearSearch() { search.value = ''; query.value = '' }
const { page, pageSize, total, pageRows, tableRef, sortBy, onSortChange } = useClientTable(filteredRows, {kindLabel: row => ({OFFICE:'办公区',ROOM:'机房',STORE:'备件库'}[row.kind as 'OFFICE'|'ROOM'|'STORE']), roomLabel: row => rooms.value.find(r=>r.id===row.roomId)?.label})

onMounted(load)
import '@/styles/asset-ops.css'
const { columnWidths, resizeColumn } = useColumnWidths({"region": 160, "name": 160, "kindLabel": 160, "roomLabel": 160, "address": 160})
</script>
<template><div class="asset-ops"><div class="ops-heading"><div><h1>区域与资产位置</h1><p>统一维护办公区、备件库和资产位置；机房位置关联已有机房，机柜及 U 位在机房资源中管理。</p></div></div><el-card shadow="never"><div v-loading="loading"><div class="ops-toolbar between"><p class="ops-muted">办公位置独立管理；机房位置关联原资源树，不重复建立机柜。</p><el-button v-if="canWrite" type="primary" @click="addSite">新增位置</el-button></div><el-input v-model="search" clearable aria-label="搜索区域、位置或地址" placeholder="搜索区域、位置或地址" style="max-width:360px;margin-bottom:12px"/><el-table :data="pageRows" :aria-busy="loading||search!==query" ref="tableRef" @sort-change="onSortChange"><el-table-column label="区域" prop="region" sortable="custom" :width="columnWidths['region']"><template #header><TableSortHeader label="区域" :width="columnWidths['region']" @resize="resizeColumn('region', $event)" @sort="sortBy('region')"/></template></el-table-column><el-table-column label="位置名称" prop="name" sortable="custom" :width="columnWidths['name']"><template #header><TableSortHeader label="位置名称" :width="columnWidths['name']" @resize="resizeColumn('name', $event)" @sort="sortBy('name')"/></template></el-table-column><el-table-column label="类型" prop="kindLabel" sortable="custom" :width="columnWidths['kindLabel']"><template #header><TableSortHeader label="类型" :width="columnWidths['kindLabel']" @resize="resizeColumn('kindLabel', $event)" @sort="sortBy('kindLabel')"/></template><template #default="{row}">{{{OFFICE:'办公区',ROOM:'机房',STORE:'备件库'}[row.kind as 'OFFICE'|'ROOM'|'STORE']}}</template></el-table-column><el-table-column label="关联机房" prop="roomLabel" sortable="custom" :width="columnWidths['roomLabel']"><template #header><TableSortHeader label="关联机房" :width="columnWidths['roomLabel']" @resize="resizeColumn('roomLabel', $event)" @sort="sortBy('roomLabel')"/></template><template #default="{row}">{{rooms.find(r=>r.id===row.roomId)?.label||'—'}}</template></el-table-column><el-table-column label="详细地址" prop="address" sortable="custom" :width="columnWidths['address']"><template #header><TableSortHeader label="详细地址" :width="columnWidths['address']" @resize="resizeColumn('address', $event)" @sort="sortBy('address')"/></template></el-table-column><el-table-column v-if="canWrite" label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="editSite(row)">编辑</el-button><el-button link type="danger" :disabled="busy" @click="deleteSite(row)">删除</el-button></template></el-table-column><template #empty><el-empty :description="sites.length ? '没有匹配结果' : '暂无记录'"><el-button v-if="query" @click="clearSearch">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="page" v-model:page-size="pageSize" :total="total" label="资产位置"/></div><el-dialog v-model="siteDialog" :title="site.id?'编辑资产位置':'新增资产位置'" width="min(550px,95vw)"><el-form label-position="top"><el-alert v-if="site.id" title="有关联业务的位置可修正区域、名称和地址；类型或关联机房的调整需先处理关联业务。" type="info" :closable="false"/><el-form-item label="区域"><el-input v-model="site.region" placeholder="例如：上海"/></el-form-item><el-form-item label="位置名称"><el-input v-model="site.name" placeholder="例如：总部办公区 / 上海机房备件库"/></el-form-item><el-form-item label="类型"><el-select v-model="site.kind"><el-option label="办公区" value="OFFICE"/><el-option label="机房" value="ROOM"/><el-option label="备件库" value="STORE"/></el-select></el-form-item><el-form-item v-if="site.kind!=='OFFICE'" label="关联原有机房"><el-select v-model="site.roomId" filterable clearable @clear="site.roomId=null"><el-option v-for="r in rooms" :key="r.id" :label="r.label" :value="r.id"/></el-select></el-form-item><el-form-item label="地址 / 说明"><el-input v-model="site.address"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="saveSite">{{site.id?'保存修改':'创建位置'}}</el-button></template></el-dialog></el-card></div></template>
